#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_OUTGOING FW_INCOMING_WAN_DMZ FW_OUTGOING_LANDMZ FW_NAT; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_PORT fws_inside-to-web && fail 'a port group named fws_inside-to-web exists; nothing was written'
named FW_GROUP_PORT fws_inside-to-servers && fail 'a port group named fws_inside-to-servers exists; nothing was written'
named FW_GROUP_IP fws_inside-no-printers && fail 'an IP group named fws_inside-no-printers exists; nothing was written'
named FW_GROUP_IP fws_servers && fail 'an IP group named fws_servers exists; nothing was written'
named FW_GROUP_IP fws_app-clients_src && fail 'an IP group named fws_app-clients_src exists; nothing was written'
named FW_GROUP_IP fws_files.example.org && fail 'an IP group named fws_files.example.org exists; nothing was written'
named FW_GROUP_IP fws_partners && fail 'an IP group named fws_partners exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_inside-no-printers --set .COMMENT 'FWShift: inside-no-printers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0-10.10.0.199
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.210-10.10.0.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_servers --set .COMMENT 'FWShift: servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.40/31
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_app-clients_src --set .COMMENT 'FWShift: 10.10.0.50, 10.10.0.60-10.10.0.69'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.50
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.60-10.10.0.69
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_files.example.org --set .COMMENT 'FWShift: files.example.org'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP files.example.org
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_partners --set .COMMENT 'FWShift: partners'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 198.51.100.0/24
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP partner.example.net
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_inside-to-web --set .COMMENT 'FWShift: inside-to-web'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 53
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_inside-to-servers --set .COMMENT 'FWShift: inside-to-servers'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 22
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 8080
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 10.10.0.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT inside-to-web
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_inside-to-web
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 10.10.0.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT inside-to-web
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.10 --set .IN_PORT 80 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'publish-web: web server published by dnatrule 1'
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT inside-to-servers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.FROM_IP" fws_inside-no-printers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_servers
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_PORT" fws_inside-to-servers
N=$((N+1))

# FW_NAT
N=$(rows FW_NAT)
gc --goto FW_NAT --add-row --set .EXT_IF ext1 --set .IN_IP 10.10.0.0/24 --set .COMMENT 'snatrule 2: snatrule id 2 from inside-net to Any service Any eif ethernet0/0 trans-to eif-ip mode dynamicport'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
